    /**
     * Method to retrieve the Subscriber via SubscriberFetchOneSummary
     * @param 	summary SubscriberFetchOneSummary 
     * @return 	SubscriberFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Subscriber getSubscriber( SubscriberFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "SubscriberFetchOneSummary arg cannot be null" );
    	
    	Subscriber entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Subscriber
        	// --------------------------------------
        	CompletableFuture<Subscriber> futureEntity = queryGateway.query(new FindSubscriberQuery( new LoadSubscriberFilter( summary.getSubscriberId() ) ), ResponseTypes.instanceOf(Subscriber.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Subscriber with id " + summary.getSubscriberId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


